<?php class ImageHelper extends Helper{	var $imgFile="";	var $imgWidth=0;	var $imgHeight=0;	var $imgType="";	var $imgAttr="";	var $type=NULL;	var $_img=NULL;	var $_error="";	function __construct($imgFile="")	{		if (!function_exists("imagecreate"))		{			$this->_error="Error: GD Library is not available.";			return false;		}		$this->type=Array(1 => 'GIF', 2 => 'JPG', 3 => 'PNG', 4 => 'SWF', 5 => 'PSD', 6 => 'BMP', 7 => 'TIFF', 8 => 'TIFF', 9 => 'JPC', 10 => 'JP2', 11 => 'JPX', 12 => 'JB2', 13 => 'SWC', 14 => 'IFF', 15 => 'WBMP', 16 => 'XBM');		if(!empty($imgFile))		$this->setImage($imgFile);	}	function error()	{		return $this->_error;	}	function setImage($imgFile)	{		$this->imgFile=$imgFile;		return $this->_createImage();	}	function close()	{		return @imagedestroy($this->_img);	}	function resize_limitwh($imgwidth,$imgheight,$newfile=NULL)	{		list($width, $height, $type, $attr) = @getimagesize($this->imgFile);		if($width > $imgwidth)		$image_per = floor(($imgwidth * 100) / $width);		if(floor(($height * $image_per)/100)>$imgheight)		$image_per = floor(($imgheight * 100) / $height);		$this->resize_percentage($image_per,$newfile);	}	function resize_custom_limit($imgwidth,$imgheight,$newfile=NULL)	{		list($width, $height, $type, $attr) = @getimagesize($this->imgFile);		$new_w=$width;		$new_h=$height;		if($width > $imgwidth)		{			$new_w=$imgwidth;			$new_h=($imgwidth/$width) * $height;		}		if($new_h > $imgheight)		{			$new_w=($imgheight/$new_h) * $new_w;			$new_h=$imgheight;		}		if($new_h!=$height || $new_w!=$width)		$this->resize($new_w,$new_h,$newfile);	}	function resize_percentage($percent=100,$newfile=NULL)	{		$newWidth=($this->imgWidth*$percent)/100;		$newHeight=($this->imgHeight*$percent)/100;		return $this->resize($newWidth,$newHeight,$newfile);	}	function resize_xypercentage($xpercent=100,$ypercent=100,$newfile=NULL)	{		$newWidth=($this->imgWidth*$xpercent)/100;		$newHeight=($this->imgHeight*$ypercent)/100;		return $this->resize($newWidth,$newHeight,$newfile);	}	function resize($width,$height,$newfile=NULL)	{		if(empty($this->imgFile))		{			$this->_error="File name is not initialised.";			return false;		}		if($this->imgWidth<=0 || $this->imgHeight<=0)		{			$this->_error="Could not resize given image";			return false;		}		if($width<=0)		$width=$this->imgWidth;		if($height<=0)		$height=$this->imgHeight;					return $this->_resize($width,$height,$newfile);	}		function _getImageInfo()	{		@list($this->imgWidth,$this->imgHeight,$type,$this->imgAttr)=@getimagesize($this->imgFile);		$this->imgType=$this->type[$type];	}		function _createImage()	{		$this->_getImageInfo($this->imgFile);		if($this->imgType=='GIF')		{			$this->_img=@imagecreatefromgif($this->imgFile);		}		elseif($this->imgType=='JPG')		{			$this->_img=@imagecreatefromjpeg($this->imgFile);		}		elseif($this->imgType=='PNG')		{			$this->_img=@imagecreatefrompng($this->imgFile);		}		if(!$this->_img || !@is_resource($this->_img))		{			$this->_error="Error loading ".$this->imgFile;			return false;		}		return true;	}	function _resize($width,$height,$newfile=NULL)        {			if($this->imgWidth!=$width || $this->imgHeight!=$height)	{		if (!function_exists("imagecreate"))		{			$this->_error="Error: GD Library is not available.";			return false;		}		$newimg=@imagecreatetruecolor($width,$height);			if($this->imgType=='PNG')			{				$transperant=imagecolorallocatealpha($newimg, 0, 255, 0, 127);				imagefill($newimg, 0, 0, $transperant);			}		@imagecopyresampled ( $newimg, $this->_img, 0,0,0,0, $width, $height, $this->imgWidth,$this->imgHeight);		if(!empty($newfile))		{			if(!@preg_match("/\..*+$/",@basename($newfile)))			{				if(@preg_match("/\..*+$/",@basename($this->imgFile),$matches))				$newfile=$newfile.$matches[0];			}		}		if($this->imgType=='GIF')		{			if(!empty($newfile))			@imagegif($newimg,$newfile);			else			{				@header("Content-type: image/gif");				@imagegif($newimg);			}		}		elseif($this->imgType=='JPG')		{			if(!empty($newfile))			@imagejpeg($newimg,$newfile);			else			{				@header("Content-type: image/jpeg");				@imagejpeg($newimg);			}		}		elseif($this->imgType=='PNG')		{        imagealphablending($newimg, false);        imagesavealpha($newimg, true);			if(!empty($newfile))			@imagepng($newimg,$newfile);			else			{				@header("Content-type: image/png");				@imagepng($newimg);                }            }            @imagedestroy($newimg);			}        }        function get_image_width()        {        	return $this->imgWidth;        }        function get_image_height()        {        	return $this->imgHeight;        }      }?>